Score 181 | Comments 70 (<a href="https://news.ycombinator.com/item?id=29941801">thread link</a>) | @CosmosSeb
<br/>
January 14, 2022 | https://muted.io/major-minor-scales/ | <a href="https://web.archive.org/web/*/https://muted.io/major-minor-scales/">archive.org</a>
<br/><!-- hnss:readable-content --><hr/><div id="readability-page-1" class="page"><div><p>💫 Here's a <em>visual &amp; interactive</em> reference for all the major and natural minor scales, their notes/pitches, layout on the piano keyboard, chords in the key of, and their relative minor or major. Use the banner at the bottom to jump to the different scales.</p><svg width="22" height="146" xmlns="http://www.w3.org/2000/svg"><g stroke="none" stroke-width="1" fill="none" fill-rule="evenodd" stroke-linecap="round" stroke-linejoin="round"><g transform="translate(1.667 .667)" stroke="#E5BFD4" stroke-width="2.667"><path id="Path" d="M9.833.833l-.5 142.834M18.667 134.333l-9.334 9.334L0 134.333"></path></g></g></svg><h2 id="major-scales">Major Scales</h2><div x-data="{ lockedScale: 'c_major' }" x-init="
  document.addEventListener('keydown', function (e) {
    if (e.keyCode == 49) {
      e.preventDefault();
      if (!fired1) {
        triggerNoteOrChord(chord_data[lockedScale][0][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(1)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][0][2].split(','));
        fired1 = true;
      }
    }
    if (e.keyCode == 50) {
      e.preventDefault();
      if (!fired2) {
        triggerNoteOrChord(chord_data[lockedScale][1][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(2)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][1][2].split(','));
        fired2 = true;
      }
    }
    if (e.keyCode == 51) {
      e.preventDefault();
      if (!fired3) {
        triggerNoteOrChord(chord_data[lockedScale][2][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(3)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][2][2].split(','));
        fired3 = true;
      }
    }
    if (e.keyCode == 52) {
      e.preventDefault();
      if (!fired4) {
        triggerNoteOrChord(chord_data[lockedScale][3][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(4)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][3][2].split(','));
        fired4 = true;
      }
    }
    if (e.keyCode == 53) {
      e.preventDefault();
      if (!fired5) {
        triggerNoteOrChord(chord_data[lockedScale][4][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(5)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][4][2].split(','));
        fired5 = true;
      }
    }
    if (e.keyCode == 54) {
      e.preventDefault();
      if (!fired6) {
        triggerNoteOrChord(chord_data[lockedScale][5][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(6)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][5][2].split(','));
        fired6 = true;
      }
    }
    if (e.keyCode == 55) {
      e.preventDefault();
      if (!fired7) {
        triggerNoteOrChord(chord_data[lockedScale][6][1]);
        document.querySelector(`.${ lockedScale } .chord-pill:nth-child(7)`).classList.add('keypress-active');
        flashChordAlt(lockedScale, chord_data[lockedScale][6][2].split(','));
        fired7 = true;
      }
    }
  });
  document.addEventListener('keyup', function (e) {
    if (e.keyCode == 49) {
      e.preventDefault();
      fired1 = false;
      releaseNoteOrChord(chord_data[lockedScale][0][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(1)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][0][2].split(','));
    }
    if (e.keyCode == 50) {
      e.preventDefault();
      fired2 = false;
      releaseNoteOrChord(chord_data[lockedScale][1][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(2)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][1][2].split(','));
    }
    if (e.keyCode == 51) {
      e.preventDefault();
      fired3 = false;
      releaseNoteOrChord(chord_data[lockedScale][2][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(3)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][2][2].split(','));
    }
    if (e.keyCode == 52) {
      e.preventDefault();
      fired4 = false;
      releaseNoteOrChord(chord_data[lockedScale][3][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(4)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][3][2].split(','));
    }
    if (e.keyCode == 53) {
      e.preventDefault();
      fired5 = false;
      releaseNoteOrChord(chord_data[lockedScale][4][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(5)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][4][2].split(','));
    }
    if (e.keyCode == 54) {
      e.preventDefault();
      fired6 = false;
      releaseNoteOrChord(chord_data[lockedScale][5][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(6)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][5][2].split(','));
    }
    if (e.keyCode == 55) {
      e.preventDefault();
      fired7 = false;
      releaseNoteOrChord(chord_data[lockedScale][6][1]);
      document.querySelector(`.${ lockedScale } .chord-pill:nth-child(7)`).classList.remove('keypress-active');
      flashChordReleaseAlt(lockedScale, chord_data[lockedScale][6][2].split(','));
    }
  });
"><div x-data=""><p>First, a reference chart of the major scales, with keys in order of 5ths, as with the <a href="https://muted.io/circle-of-fifths/">circle of fifths</a>. This illustrates that there's just one note difference (at the 7th scale degree) between scales formed from keys that are separated by a fifth. Hit play on any scale to play its pitches up and down:</p><table><thead><tr><th></th><th>I</th><th>ii</th><th>iii</th><th>IV</th><th>V</th><th>vi</th><th>vii°</th><th>I</th></tr></thead><tbody><tr><td></td><td><strong>C</strong></td><td>D</td><td>E</td><td>F</td><td>G</td><td>A</td><td>B</td><td><strong>C</strong></td></tr><tr><td></td><td><strong>G</strong></td><td>A</td><td>B</td><td>C</td><td>D</td><td>E</td><td>F♯</td><td><strong>G</strong></td></tr><tr x-data="" x-intersect.once="$store.minorStatus.showMinor(); initiateSampler();"><td></td><td><strong>D</strong></td><td>E</td><td>F♯</td><td>G</td><td>A</td><td>B</td><td>C♯</td><td><strong>D</strong></td></tr><tr><td></td><td><strong>A</strong></td><td>B</td><td>C♯</td><td>D</td><td>E</td><td>F♯</td><td>G♯</td><td><strong>A</strong></td></tr><tr><td></td><td><strong>E</strong></td><td>F♯</td><td>G♯</td><td>A</td><td>B</td><td>C♯</td><td>D♯</td><td><strong>E</strong></td></tr><tr><td></td><td><strong>B</strong></td><td>C♯</td><td>D♯</td><td>E</td><td>F♯</td><td>G♯</td><td>A♯</td><td><strong>B</strong></td></tr><tr><td></td><td><strong>F♯</strong></td><td>G♯</td><td>A♯</td><td>B</td><td>C♯</td><td>D♯</td><td>E♯</td><td><strong>F♯</strong></td></tr><tr><td></td><td><strong>D♭</strong></td><td>E♭</td><td>F</td><td>G♭</td><td>A♭</td><td>B♭</td><td>C</td><td><strong>D♭</strong></td></tr><tr><td></td><td><strong>A♭</strong></td><td>B♭</td><td>C</td><td>D♭</td><td>E♭</td><td>F</td><td>G</td><td><strong>A♭</strong></td></tr><tr><td></td><td><strong>E♭</strong></td><td>F</td><td>G</td><td>A♭</td><td>B♭</td><td>C</td><td>D</td><td><strong>E♭</strong></td></tr><tr><td></td><td><strong>B♭</strong></td><td>C</td><td>D</td><td>E♭</td><td>F</td><td>G</td><td>A</td><td><strong>B♭</strong></td></tr><tr><td></td><td><strong>F</strong></td><td>G</td><td>A</td><td>B♭</td><td>C</td><td>D</td><td>E</td><td><strong>F</strong></td></tr></tbody></table></div><p>And now for each of the major scales in more detail. Tip: <strong>click the lock icon</strong> to trigger the chords of that scale using keys 1 through 7 on your keyboard.</p><svg width="22" height="146" xmlns="http://www.w3.org/2000/svg"><g stroke="none" stroke-width="1" fill="none" fill-rule="evenodd" stroke-linecap="round" stroke-linejoin="round"><g transform="translate(1.667 .667)" stroke="#E5BFD4" stroke-width="2.667"><path id="Path" d="M9.833.833l-.5 142.834M18.667 134.333l-9.334 9.334L0 134.333"></path></g></g></svg><hr><h2 id="minor-scales">Minor Scales</h2><div x-data=""><p>The following represents the <strong>natural minor scales</strong>, which is the default when we refer to minor scales.</p><p>As with the major scales, let's start with a reference chart of the minor scales with keys in order of 5ths. With minor scales, the different note between scales with keys separated by a 5th is at the 2nd scale degree. Hit play on any scale to play its pitches up and down:</p><table><thead><tr><th></th><th>i</th><th>ii°</th><th>III</th><th>iv</th><th>v</th><th>VI</th><th>VII</th><th>i</th></tr></thead><tbody><tr><td></td><td><strong>A</strong></td><td>B</td><td>C</td><td>D</td><td>E</td><td>F</td><td>G</td><td><strong>A</strong></td></tr><tr><td></td><td><strong>E</strong></td><td>F♯</td><td>G</td><td>A</td><td>B</td><td>C</td><td>D</td><td><strong>E</strong></td></tr><tr><td></td><td><strong>B</strong></td><td>C♯</td><td>D</td><td>E</td><td>F♯</td><td>G</td><td>A</td><td><strong>B</strong></td></tr><tr><td></td><td><strong>F♯</strong></td><td>G♯</td><td>A</td><td>B</td><td>C♯</td><td>D</td><td>E</td><td><strong>F♯</strong></td></tr><tr><td></td><td><strong>C♯</strong></td><td>D♯</td><td>E</td><td>F♯</td><td>G♯</td><td>A</td><td>B</td><td><strong>C♯</strong></td></tr><tr><td></td><td><strong>G♯</strong></td><td>A♯</td><td>B</td><td>C♯</td><td>D♯</td><td>E</td><td>F♯</td><td><strong>G♯</strong></td></tr><tr><td></td><td><strong>D♯</strong></td><td>E♯</td><td>F♯</td><td>G♯</td><td>A♯</td><td>B</td><td>C♯</td><td><strong>D♯</strong></td></tr><tr><td></td><td><strong>B♭</strong></td><td>C</td><td>D♭</td><td>E♭</td><td>F</td><td>G♭</td><td>A♭</td><td><strong>B♭</strong></td></tr><tr><td></td><td><strong>F</strong></td><td>G</td><td>A♭</td><td>B♭</td><td>C</td><td>D♭</td><td>E♭</td><td><strong>F</strong></td></tr><tr><td></td><td><strong>C</strong></td><td>D</td><td>E♭</td><td>F</td><td>G</td><td>A♭</td><td>B♭</td><td><strong>C</strong></td></tr><tr><td></td><td><strong>G</strong></td><td>A</td><td>B♭</td><td>C</td><td>D</td><td>E♭</td><td>F</td><td><strong>G</strong></td></tr><tr><td></td><td><strong>D</strong></td><td>E</td><td>F</td><td>G</td><td>A</td><td>B♭</td><td>C</td><td><strong>D</strong></td></tr></tbody></table></div><p>And now each of the natural minor scales in more detail. The full reference for each of the minor scales also includes the harmonic and melodic minors, and you can also reference the <a href="https://muted.io/harmonic-minor-scale/">harmonic minor scale here</a> and the <a href="https://muted.io/melodic-minor-scale/">melodic minor scale here</a>. Again, <strong>you can lock the chords</strong> and use keys 1-7 on your keyboard to trigger them.</p><svg width="22" height="146" xmlns="http://www.w3.org/2000/svg"><g stroke="none" stroke-width="1" fill="none" fill-rule="evenodd" stroke-linecap="round" stroke-linejoin="round"><g transform="translate(1.667 .667)" stroke="#E5BFD4" stroke-width="2.667"><path id="Path" d="M9.833.833l-.5 142.834M18.667 134.333l-9.334 9.334L0 134.333"></path></g></g></svg><template x-data="" x-if="!$store.minorStatus.minorVisible"><p class="text-center"><button @click="initiateSampler(); $store.minorStatus.showMinor();" class="bg-cyan rounded-full button p-5 uppercase text-xs sm:text-sm font-bold sm:w-auto text-white mt-12">load natural minor scales...</button></p></template><template x-data="" x-if="$store.minorStatus.minorVisible"><div class="grid grid-cols-1 xl:grid-cols-2 3xl:grid-cols-3 gap-x-4 gap-y-16 mt-4 mb-16"><div class="scale c_minor dark-bg md:rounded-lg hover:shadow px-4 py-2 text-center flex flex-col justify-between"><h3 id="c-minor-scale">C Minor Scale</h3><div class="highlights flex flex-wrap justify-evenly mb-4" x-data=""><p class="not-first-p shadow-md rounded-full pale-bg">notes: C D E<sub>♭</sub> F G A<sub>♭</sub> B<sub>♭</sub></p><p class="pale-bg shadow-md rounded-full">relative major: <span class="highlight"><a href="#ds-major-scale">E♭ major</a></span></p><button @click="play(['C3', 'D3', 'Eb3', 'F3', 'G3', 'Ab3', 'Bb3', 'C4', 'Bb3', 'Ab3', 'G3', 'F3', 'Eb3', 'D3', 'C3']); flash('c-min-kb');" aria-label="Play C minor scale pitches" title="play C minor scale up and down" class="play-btn pale-bg rounded-full shadow-md cursor-pointer button p-4"><img width="28" height="28" alt="" src="/images/play.svg"></button></div><ul id="c-min-kb" class="keyboard flex justify-center" x-data=""><li class="white c touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('C3');" @mouseup="releaseNoteOrChord('C3')" @touchstart.prevent="triggerNoteOrChord('C3');" @touchend.prevent="releaseNoteOrChord('C3')"><span>C</span></li><li class="black cs"></li><li class="white d touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('D3');" @mouseup="releaseNoteOrChord('D3')" @touchstart.prevent="triggerNoteOrChord('D3');" @touchend.prevent="releaseNoteOrChord('D3')"><span>D</span></li><li class="black ds touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('Eb3');" @mouseup="releaseNoteOrChord('Eb3')" @touchstart.prevent="triggerNoteOrChord('Eb3');" @touchend.prevent="releaseNoteOrChord('Eb3')"><span>E<sub>♭</sub></span></li><li class="white e"></li><li class="white f touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('F3');" @mouseup="releaseNoteOrChord('F3')" @touchstart.prevent="triggerNoteOrChord('F3');" @touchend.prevent="releaseNoteOrChord('F3')"><span>F</span></li><li class="black fs"></li><li class="white g touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('G3');" @mouseup="releaseNoteOrChord('G3')" @touchstart.prevent="triggerNoteOrChord('G3');" @touchend.prevent="releaseNoteOrChord('G3')"><span>G</span></li><li class="black gs touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('Ab3');" @mouseup="releaseNoteOrChord('Ab3')" @touchstart.prevent="triggerNoteOrChord('Ab3');" @touchend.prevent="releaseNoteOrChord('Ab3')"><span>A<sub>♭</sub></span></li><li class="white a"></li><li class="black as touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('Bb3');" @mouseup="releaseNoteOrChord('Bb3')" @touchstart.prevent="triggerNoteOrChord('Bb3');" @touchend.prevent="releaseNoteOrChord('Bb3')"><span>B<sub>♭</sub></span></li><li class="white b"></li><li class="white c touch-trigger pressed cursor-pointer" @mousedown="triggerNoteOrChord('C4');" @mouseup="releaseNoteOrChord('C4')" @touchstart.prevent="triggerNoteOrChord('C4');" @touchend.prevent="releaseNoteOrChord('C4')"><span>C</span></li><li class="black cs"></li><li class="white d"></li><li class="black ds"></li><li class="white e"></li><li class="white f"></li><li class="black fs"></li><li class="white g"></li><li class="black gs"></li><li class="white a"></li><li class="black as"></li><li class="white b"></li><li class="white c"></li></ul><h4 @click="lockedScale = 'c_minor'" title="Lock to trigger chords using keyboard" class="!text-base uppercase font-bold cursor-pointer"><svg class="lock-icon" :class="lockedScale === 'c_minor' ? 'text-magenta-bright' : 'text-base00'" xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg> chords in the key of C minor</h4><div class="flex flex-wrap justify-around mb-6" x-data=""><button class="chord-pill pale-bg" title="Play Cmin chord" @mousedown="triggerNoteOrChord(['C3', 'Eb3', 'G3']); flashChord('c-min-kb', [1,4,8]);" @mouseup="releaseNoteOrChord(['C3', 'Eb3', 'G3']); flashChordRelease('c-min-kb', [1,4,8]);" @touchstart.prevent="triggerNoteOrChord(['C3', 'Eb3', 'G3']); flashChord('c-min-kb', [1,4,8]);" @touchend.prevent="releaseNoteOrChord(['C3', 'Eb3', 'G3']); flashChordRelease('c-min-kb', [1,4,8]);">Cmin</button> <button class="chord-pill pale-bg" title="Play Ddim chord" @mousedown="triggerNoteOrChord(['D3', 'F3', 'Ab3']); flashChord('c-min-kb', [3,6,9]);" @mouseup="releaseNoteOrChord(['D3', 'F3', 'Ab3']); flashChordRelease('c-min-kb', [3,6,9]);" @touchstart.prevent="triggerNoteOrChord(['D3', 'F3', 'Ab3']); flashChord('c-min-kb', [3,6,9]);" @touchend.prevent="releaseNoteOrChord(['D3', 'F3', 'Ab3']); flashChordRelease('c-min-kb', [3,6,9]);">Ddim</button> <button class="chord-pill pale-bg" title="Play Ebmaj chord" @mousedown="triggerNoteOrChord(['Eb3', 'G3', 'Bb3']); flashChord('c-min-kb', [4,8,11]);" @mouseup="releaseNoteOrChord(['Eb3', 'G3', 'Bb3']); flashChordRelease('c-min-kb', [4,8,11]);" @touchstart.prevent="triggerNoteOrChord(['Eb3', 'G3', 'Bb3']); flashChord('c-min-kb', [4,8,11]);" @touchend.prevent="releaseNoteOrChord(['Eb3', 'G3', 'Bb3']); flashChordRelease('c-min-kb', [4,8,11]);">Ebmaj</button> <button class="chord-pill pale-bg" title="Play Fmin chord" @mousedown="triggerNoteOrChord(['F3', 'Ab3', 'C4']); flashChord('c-min-kb', [6,9,13]);" @mouseup="releaseNoteOrChord(['F3', 'Ab3', 'C4']); flashChordRelease('c-min-kb', [6,9,13]);" @touchstart.prevent="triggerNoteOrChord(['F3', 'Ab3', 'C4']); flashChord('c-min-kb', [6,9,13]);" @touchend.prevent="releaseNoteOrChord(['F3', 'Ab3', 'C4']); flashChordRelease('c-min-kb', [6,9,13]);">Fmin</button> <button class="chord-pill pale-bg" title="Play Gmin chord" @mousedown="triggerNoteOrChord(['G3', 'Bb3', 'D4']); flashChord('c-min-kb', [8,11,15]);" @mouseup="releaseNoteOrChord(['G3', 'Bb3', 'D4']); flashChordRelease('c-min-kb', [8,11,15]);" @touchstart.prevent="triggerNoteOrChord(['G3', 'Bb3', 'D4']); flashChord('c-min-kb', [8,11,15]);" @touchend.prevent="releaseNoteOrChord(['G3', 'Bb3', 'D4']); flashChordRelease('c-min-kb', [8,11,15]);">Gmin</button> <button class="chord-pill pale-bg" title="Play Abmaj chord" @mousedown="triggerNoteOrChord(['Ab3', 'C4', 'Eb4']); flashChord('c-min-kb', [9,13,16]);" @mouseup="releaseNoteOrChord(['Ab3', 'C4', 'Eb4']); flashChordRelease('c-min-kb', [9,13,16]);" @touchstart.prevent="triggerNoteOrChord(['Ab3', 'C4', 'Eb4']); flashChord('c-min-kb', [9,13,16]);" @touchend.prevent="releaseNoteOrChord(['Ab3', 'C4', 'Eb4']); flashChordRelease('c-min-kb', [9,13,16]);">Abmaj</button> <button class="chord-pill pale-bg" title="Play Bbmaj chord" @mousedown="triggerNoteOrChord(['Bb3', 'D4', 'F4']); flashChord('c-min-kb', [11,15,18]);" @mouseup="releaseNoteOrChord(['Bb3', 'D4', 'F4']); flashChordRelease('c-min-kb', [11,15,18]);" @touchstart.prevent="triggerNoteOrChord(['Bb3', 'D4', 'F4']); flashChord('c-min-kb', [11,15,18]);" @touchend.prevent="releaseNoteOrChord(['Bb3', 'D4', 'F4']); flashChordRelease('c-min-kb', [11,15,18]);">Bbmaj</button></div><a href="/c-minor-scale/" class="neon-luv featured-link pale-bg">→ full C minor scale piano reference</a></div><div class="scale d_minor dark-bg md:rounded-lg hover:shadow px-4 py-2 text-center flex flex-col justify-between"><h3 id="d-minor-scale">D Minor Scale</h3><div class="highlights flex flex-wrap justify-evenly mb-4" x-data=""><p class="not-first-p shadow-md rounded-full pale-bg">notes: D E F G A B<sub>♭</sub> C</p><p class="pale-bg shadow-md rounded-full">relative major: <span class="highlight"><a href="#f-major-scale">F major</a></span></p><button @click="play(['D3', 'E3', 'F3